//! Google Docs API v1 implementation.//!//! All API calls go through the host's HTTP capability, which handles//! credential injection and rate limiting. The WASM tool never sees//! the actual OAuth token.use crate::near::agent::host;use crate::types::*;const DOCS_API_BASE: &str = "https://docs.googleapis.com/v1/documents";/// Make a Google Docs API call.fn api_call(method: &str, path: &str, body: Option<&str>) -> Result<String, String> {    let url = if path.is_empty() {        DOCS_API_BASE.to_string()    } else {        format!("{}/{}", DOCS_API_BASE, path)    };    let headers = if body.is_some() {        r#"{"Content-Type": "application/json"}"#    } else {        "{}"    };    let body_bytes = body.map(|b| b.as_bytes().to_vec());    host::log(        host::LogLevel::Debug,        &format!("Google Docs API: {} {}", method, url),    );    let response = host::http_request(method, &url, headers, body_bytes.as_deref(), None)?;    if response.status < 200 || response.status >= 300 {        let body_text = String::from_utf8_lossy(&response.body);        return Err(format!(            "Google Docs API returned status {}: {}",            response.status, body_text        ));    }    if response.body.is_empty() {        return Ok(String::new());    }    String::from_utf8(response.body).map_err(|e| format!("Invalid UTF-8 in response: {}", e))}/// Send a batchUpdate to the document and return the parsed response.